from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json

PAGE = '''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><title>服務實驗</title><body><h1>展覽服務實驗</h1><label>訊息 <input id="message" value="demo" maxlength="20"></label><button id="get">讀服務資料</button><button id="post">提交訊息</button><pre id="out"></pre><script>
const out=document.getElementById('out');
document.getElementById('get').onclick=async()=>{try{const r=await fetch('/api/info');out.textContent=r.status+' '+await r.text();}catch(e){out.textContent='連線失敗';}};
document.getElementById('post').onclick=async()=>{try{const r=await fetch('/api/echo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:document.getElementById('message').value})});out.textContent=r.status+' '+await r.text();}catch(e){out.textContent='連線失敗';}};
</script></body></html>'''
class Handler(BaseHTTPRequestHandler):
    def reply(self, status, data, kind='application/json; charset=utf-8'):
        raw = (json.dumps(data, ensure_ascii=False) if not isinstance(data, str) else data).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', kind)
        self.send_header('Content-Length', str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)
    def do_GET(self):
        if self.path == '/': self.reply(200, PAGE, 'text/html; charset=utf-8')
        elif self.path == '/api/info': self.reply(200, {'service':'exhibition', 'mode':'local-demo'})
        else: self.reply(404, {'error':'not found'})
    def do_POST(self):
        if self.path != '/api/echo': self.reply(404, {'error':'not found'}); return
        try:
            size = int(self.headers.get('Content-Length', '0'))
            if size < 1 or size > 1024: raise ValueError('size')
            data = json.loads(self.rfile.read(size))
            text = data.get('message') if isinstance(data, dict) else None
            if not isinstance(text, str) or not 1 <= len(text.strip()) <= 20: raise ValueError('message')
        except (ValueError, json.JSONDecodeError):
            self.reply(400, {'error':'message must contain 1-20 non-blank characters'}); return
        self.reply(200, {'received':text.strip()})
print('Open http://127.0.0.1:8000 ; Ctrl+C to stop')
ThreadingHTTPServer(('127.0.0.1', 8000), Handler).serve_forever()
