'use strict';
const byId = id => document.getElementById(id);
function status(text) { byId('status').textContent = text; }
async function request(path, method = 'GET', data) {
  const options = { method, credentials: 'same-origin' };
  if (data !== undefined) {
    options.headers = { 'Content-Type': 'application/json' };
    options.body = JSON.stringify(data);
  }
  let response;
  try { response = await fetch(path, options); }
  catch (error) { throw new Error('網絡錯誤：尚未確認請求結果，請恢復連線後讀回核對。'); }
  const result = await response.json();
  if (!response.ok) throw new Error(response.status + '：' + result.error);
  return { code: response.status, data: result };
}
function showProfile(profile) {
  byId('profile').textContent = profile.studentId + '／' + profile.name + '／年齡 ' + profile.age;
  byId('age').value = profile.age;
}
async function loadProfile() {
  const result = await request('/api/profile');
  showProfile(result.data);
  status(result.code + '：已讀取自己的資料。');
}
byId('loginForm').addEventListener('submit', async event => {
  event.preventDefault();
  try {
    await request('/api/login', 'POST', { username: byId('username').value, password: byId('password').value });
    byId('password').value = '';
    await loadProfile();
  } catch (error) { status(error.message); }
});
byId('load').addEventListener('click', async () => {
  try { await loadProfile(); } catch (error) { status(error.message); }
});
byId('ageForm').addEventListener('submit', async event => {
  event.preventDefault();
  const text = byId('age').value.trim();
  if (!byId('bypass').checked && (!/^\d+$/.test(text) || Number(text) < 12 || Number(text) > 100)) {
    status('客戶端檢查：請輸入 12 至 100 的整數。'); return;
  }
  try {
    const result = await request('/api/profile', 'POST', { age: Number(text) });
    showProfile(result.data);
    status(result.code + '：已儲存，並以伺服器回應更新畫面。');
  } catch (error) { status(error.message + '；輸入保留，請核對後再試。'); }
});
byId('logout').addEventListener('click', async () => {
  try {
    await request('/api/logout', 'POST', {});
    byId('profile').textContent = '已登出'; byId('age').value = ''; status('會話已撤銷。');
  } catch (error) { status(error.message); }
});

from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlsplit
from http.cookies import SimpleCookie
from contextlib import closing
import json, secrets, sqlite3, time

ROOT = Path(__file__).resolve().parent
DB = ROOT / 'profiles.sqlite3'
USERS = {'alice': ('learn-only', 'S01'), 'bob': ('learn-only', 'S02')}
SESSIONS = {}  # 只供本機示範；重新啟動便清空
with closing(sqlite3.connect(DB)) as db, db:
    db.execute('CREATE TABLE IF NOT EXISTS PROFILE (StudentID TEXT PRIMARY KEY, Name TEXT NOT NULL, Age INTEGER NOT NULL)')
    db.executemany('INSERT OR IGNORE INTO PROFILE VALUES (?, ?, ?)', [('S01', '示例甲', 16), ('S02', '示例乙', 17)])

def profile(uid, age=None):
    with closing(sqlite3.connect(DB)) as db, db:
        db.row_factory = sqlite3.Row
        if age is not None:
            db.execute('UPDATE PROFILE SET Age=? WHERE StudentID=?', (age, uid))
        row = db.execute('SELECT StudentID, Name, Age FROM PROFILE WHERE StudentID=?', (uid,)).fetchone()
        return {'studentId': row['StudentID'], 'name': row['Name'], 'age': row['Age']}

class Handler(BaseHTTPRequestHandler):
    def reply(self, code, payload, cookie=None):
        body = json.dumps(payload, ensure_ascii=False).encode('utf-8')
        self.send_response(code)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Cache-Control', 'no-store')
        if cookie: self.send_header('Set-Cookie', cookie)
        self.end_headers()
        self.wfile.write(body)

    def session(self):
        jar = SimpleCookie()
        try: jar.load(self.headers.get('Cookie', ''))
        except Exception: return None, None
        sid = jar['sid'].value if 'sid' in jar else None
        record = SESSIONS.get(sid)
        if record and record[1] > time.time(): return sid, record[0]
        if record: SESSIONS.pop(sid, None)
        return sid, None

    def do_GET(self):
        path = urlsplit(self.path).path
        if path == '/api/profile':
            _, uid = self.session()
            if not uid: return self.reply(401, {'error': '請先登入或重新登入'})
            return self.reply(200, profile(uid))
        files = {'/': ('index.html', 'text/html; charset=utf-8'), '/style.css': ('style.css', 'text/css; charset=utf-8'), '/app.js': ('app.js', 'text/javascript; charset=utf-8')}
        if path not in files: return self.reply(404, {'error': '找不到資源'})
        filename, content_type = files[path]
        body = (ROOT / filename).read_bytes()
        self.send_response(200)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        path = urlsplit(self.path).path
        try:
            size = int(self.headers.get('Content-Length', '0'))
            if not 0 < size <= 4096: raise ValueError()
            data = json.loads(self.rfile.read(size))
            if not isinstance(data, dict): raise ValueError()
        except (ValueError, UnicodeDecodeError):
            return self.reply(400, {'error': '請提供不超過 4096 bytes 的 JSON 物件'})
        if path == '/api/login':
            username, password = data.get('username'), data.get('password')
            if not isinstance(username, str) or not isinstance(password, str):
                return self.reply(400, {'error': '帳戶及密碼必須為文字'})
            user = USERS.get(username)
            if not user or password != user[0]: return self.reply(401, {'error': '登入資料不符'})
            old_sid, _ = self.session()
            SESSIONS.pop(old_sid, None)
            sid = secrets.token_urlsafe(24)
            SESSIONS[sid] = (user[1], time.time() + 900)
            return self.reply(200, {'message': '已登入'}, 'sid=' + sid + '; HttpOnly; SameSite=Lax; Path=/')
        if path == '/api/logout':
            sid, _ = self.session()
            SESSIONS.pop(sid, None)
            return self.reply(200, {'message': '已登出'}, 'sid=; Max-Age=0; HttpOnly; SameSite=Lax; Path=/')
        if path == '/api/profile':
            _, uid = self.session()
            if not uid: return self.reply(401, {'error': '請先登入或重新登入'})
            age = data.get('age')
            if type(age) is not int or not 12 <= age <= 100:
                return self.reply(400, {'error': '年齡必須為 12 至 100 的整數'})
            return self.reply(200, profile(uid, age))
        return self.reply(404, {'error': '找不到服務'})

if __name__ == '__main__':
    print('本機示範：http://127.0.0.1:8000 ，Ctrl+C 停止')
    ThreadingHTTPServer(('127.0.0.1', 8000), Handler).serve_forever()
